/**
 * Real, parseable two-page PDFs with CJK text and layout coordinates.
 * They contain blank form labels/instructions only and no applicant data.
 * The fixtures were generated with ReportLab's STSong-Light CID font.
 */
export function realFundingPdfFixture(name: RealFundingPdfFixtureName): Buffer {
  return Buffer.from(BASE64_FIXTURES[name].join(''), 'base64');
}

export function realFundingPdfFixtureSha256(name: RealFundingPdfFixtureName): string {
  return createHash('sha256').update(realFundingPdfFixture(name)).digest('hex');
}
